// ---------------------------------------------------------------- routes
const routeGroup = new THREE.Group();
scene.add(routeGroup);
function routeMesh(route, color) {
  const pts = [];
  for (let i = 0; i < route.path.length - 1; i++) {
    const [x0, y0] = route.path[i], [x1, y1] = route.path[i + 1];
    const n = Math.max(1, Math.ceil(Math.hypot(x1 - x0, y1 - y0) / 6));
    for (let s = 0; s < n; s++) pts.push(groundV(x0 + ((x1 - x0) * s) / n, y0 + ((y1 - y0) * s) / n, 1.5));
  }
  const last = route.path.at(-1);
  pts.push(groundV(last[0], last[1], 1.5));
  const mesh = new THREE.Mesh(
    new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), Math.min(pts.length * 2, 5000), 1.6, 6, false),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.95 }),
  );
  mesh.layers.set(3); // 第三人稱／俯瞰看的路線
  routeGroup.add(mesh);
  // 第一人稱：貼地的細線（粗管子在眼睛高度看會太大、和地面閃爍）
  const thin = new THREE.Mesh(
    new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts.map((v) => v.clone().setY(v.y + 0.4))), Math.min(pts.length * 2, 5000), 0.35, 5, false),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.95 }),
  );
  thin.layers.set(2);
  routeGroup.add(thin);
  mesh.userData.thin = thin;
  // 平板小地圖用的粗線（只在 layer 1，主畫面看不到）
  const mini = new THREE.Mesh(
    new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), Math.min(pts.length * 2, 5000), 7, 4, false),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.95, depthTest: false }),
  );
  mini.layers.set(1);
  mini.renderOrder = 900;
  routeGroup.add(mini);
  mesh.userData.mini = mini;
  return mesh;
}
function clearRoutes() {
  routeGroup.children.slice().forEach((m) => { m.geometry.dispose(); routeGroup.remove(m); });
  S.routes = {};
}
function selectRoute(key) {
  S.selected = key;
  for (const [k, r] of Object.entries(S.routes)) {
    const color = k === key ? '#1688d4' : '#95a0aa';
    r.mesh.material.color.set(color);
    r.mesh.material.opacity = k === key ? 1 : 0.25;
    if (r.mesh.userData.mini) { r.mesh.userData.mini.material.color.set(color); r.mesh.userData.mini.material.opacity = k === key ? 1 : 0.3; }
    if (r.mesh.userData.thin) { r.mesh.userData.thin.material.color.set(color); r.mesh.userData.thin.visible = k === key; }
  }
  document.querySelectorAll('.route-card').forEach((c) => c.classList.toggle('selected', c.dataset.key === key));
  $('start').disabled = !key || !!S.eva;
  updateSteps();
}
const ROUTE_TAG = { safe: 'Lower risk, avoids steep terrain', balanced: 'Shorter with moderate risk', science: 'Shortest, accepts steeper terrain' };
const ROUTE_NAME = { safe: 'Safe', balanced: 'Balanced', science: 'Science' };
function card(key, r) {
  const div = document.createElement('div');
  div.className = 'route-card';
  div.dataset.key = key;
  div.style.setProperty('--c', COLORS[key]);
  if (!r) { div.innerHTML = `<h3>${key}</h3><div>No traversable route</div>`; return div; }
  const risk = r.risk < 0.4 ? 'low' : r.risk < 0.7 ? 'medium' : 'high';
  div.innerHTML = `<div class="route-main"><span class="route-radio" aria-hidden="true"></span><div><h3>${ROUTE_NAME[key]}</h3><span class="tag">${ROUTE_TAG[key]}</span></div></div>
    <div class="stats route-stats">
      <span>↔ ${(r.length_m / 1000).toFixed(2)} km</span><span>◷ ${r.eta_min.toFixed(0)} min</span><span>△ Risk ${(r.risk * 100).toFixed(0)}%</span>
    </div>
    <details><summary>details</summary>
      <div class="stats"><span>Max slope ${r.max_slope_deg.toFixed(0)}°</span><span>Closest hazard ${r.min_clearance_m.toFixed(0)} m</span><span>Dose ${r.dose_msv.toFixed(3)} mSv</span></div>
      <ul class="notes">${r.notes.map((n) => `<li>${n}</li>`).join('')}</ul>
    </details>`;
  div.onclick = (e) => { if (e.target.tagName !== 'SUMMARY') selectRoute(key); };
  return div;
}

/** 三步驟的狀態：目前在哪一步、哪些已完成、哪些還不能用。 */
function updateSteps() {
  const planned = Object.keys(S.routes).length > 0 && !S.eva;
  const st = (id, cls) => { $(id).classList.remove('current', 'done', 'locked'); if (cls) $(id).classList.add(cls); };
  if (S.eva) { st('step1', 'done'); st('step2', 'done'); st('step3', 'current'); }
  else if (planned && S.selected) { st('step1', 'done'); st('step2', 'done'); st('step3', 'current'); }
  else if (S.goal) { st('step1', 'done'); st('step2', 'current'); st('step3', 'locked'); }
  else { st('step1', 'current'); st('step2', 'locked'); st('step3', 'locked'); }
  $('step1').classList.toggle('hidden', !!S.goal || !!S.eva);
  $('step2').classList.toggle('hidden', !S.goal || !!S.eva);
  $('step3').classList.toggle('hidden', !S.eva);
  $('dest-header').classList.toggle('hidden', !S.goal || !!S.eva);
  $('dest-name').textContent = S.goalName || 'Custom point';
  $('info-card').classList.toggle('hidden', !!S.goal);
  $('eva-header').classList.toggle('hidden', !S.eva);
  $('o2-bar-wrap').classList.toggle('hidden', !S.eva);
  $('metrics-grid').classList.toggle('hidden', !S.eva);
  $('mission-actions').classList.toggle('hidden', !S.eva);
  $('sim-events').classList.toggle('hidden', !S.eva);
  $('plan').textContent = planned ? 'Calculate routes again' : 'Calculate routes';
  if (S.eva) $('eva-route-label').textContent = `To ${S.goalName || 'target'} · ${ROUTE_NAME[S.eva.routeKey] || S.eva.routeKey} route`;
}

function selectMoreTab(id) {
  document.querySelectorAll('.more-tab').forEach((tab) => tab.classList.toggle('active', tab.dataset.tab === id));
  document.querySelectorAll('.more-pane').forEach((pane) => pane.classList.toggle('active', pane.id === id));
  $('more-overlay').classList.toggle('layers-active', id === 'tab-layers');
}
function openMore(id = 'tab-layers') {
  selectMoreTab(id);
  $('more-overlay').classList.remove('hidden');
}
function closeMore() {
  $('more-overlay').classList.add('hidden');
}

async function planRoutes() {
  if (S.eva) return;
  const t0 = performance.now();
  try {
    const res = await api.compare({ start: [S.walk.pos.x, S.walk.pos.y], goal: [S.goal.x, S.goal.y] });
    clearRoutes();
    $('routes').innerHTML = '';
    for (const key of ['safe', 'balanced', 'science']) {
      const r = res[key];
      if (r) S.routes[key] = { route: r, mesh: routeMesh(r, COLORS[key]) };
      $('routes').appendChild(card(key, r));
    }
    log(`3 routes planned on-board in ${(performance.now() - t0).toFixed(0)} ms`, 'ok');
    selectRoute(S.routes.safe ? 'safe' : Object.keys(S.routes)[0]);
    tourEvent('planned');
  } catch (e) {
    log(`Planning failed: ${e.message}`, 'bad');
  }
}
function setActiveRoute(route, key) {
  clearRoutes();
  S.routes[key] = { route, mesh: routeMesh(route, COLORS[key] || COLORS.safe) };
  S.eva.route = route;
  S.eva.routeKey = key;
}

// ---------------------------------------------------------------- EVA (walkable)
const keys = new Set();
const keyName = (e) => ({ w: 'ArrowUp', s: 'ArrowDown', a: 'ArrowLeft', d: 'ArrowRight' })[e.key.toLowerCase()] || e.key;
addEventListener('keydown', (e) => {
  const tag = e.target?.tagName;
  const typing = tag === 'INPUT' || tag === 'SELECT' || tag === 'TEXTAREA';
  if (e.key === 'Tab' || (!typing && (e.key === 'm' || e.key === 'M'))) { e.preventDefault(); setTablet(!S.tabletUp); return; }
  if (e.key === 'Escape') { setTablet(false); return; }
  if (typing) return;
  if ((e.key === 'b' || e.key === 'B') && S.eva) { deployBeacon(); return; }
  if (e.key === 'v' || e.key === 'V') { setCam(S.cam === 'first' ? 'third' : 'first'); return; }
  const k = keyName(e);
  if (k.startsWith('Arrow')) { keys.add(k); e.preventDefault(); }
});
addEventListener('keyup', (e) => keys.delete(keyName(e)));
document.querySelectorAll('#dpad button').forEach((b) => {
  b.addEventListener('pointerdown', (e) => { keys.add(b.dataset.k); e.preventDefault(); });
  ['pointerup', 'pointerleave', 'pointercancel'].forEach((ev) => b.addEventListener(ev, () => keys.delete(b.dataset.k)));
});

const feedback = new Feedback($('haptic'));
$('opt-sound').onchange = (e) => { feedback.sound = e.target.checked; feedback.unlockAudio(); };
$('opt-vibe').onchange = (e) => (feedback.vibrate = e.target.checked);

function startEva() {
  const r = S.routes[S.selected];
  if (!r) return;
  if (S.view !== '3d') setViewMode('3d');
  feedback.unlockAudio();
  const pos = S.walk.pos, bx = pos.x, by = pos.y;
  const first = r.route.path[Math.min(1, r.route.path.length - 1)];
  S.eva = {
    t: 0, o2: S.meta.params.o2_capacity_min, o2Rate: 1,
    pos, heading: Math.atan2(first[1] - by, first[0] - bx),
    est: { x: bx, y: by }, sigma: 0.5, lastLocPos: { x: bx, y: by }, locTimer: 0, locBusy: false, seed: 1,
    route: r.route, routeKey: S.selected, mode: S.selected, nav: null, loc: null,
    drift: null, returning: false, done: false, replanning: false, lastReplan: 0,
  };
  estMarker.visible = true;
  applyFog();
  $('hud').classList.remove('hidden');
  setTablet(true);
  ['start', 'plan'].forEach((id) => ($(id).disabled = true));
  ['rockfall', 'leak', 'drift', 'home', 'linkloss', 'deploy'].forEach((id) => ($(id).disabled = false));
  placeAstronaut();
  S.look.yaw = 0;
  if (S.cam === 'orbit') {
    const p = astro.position;
    controls.target.copy(p);
    camera.position.set(p.x - Math.cos(S.eva.heading) * 60, p.y + 35, p.z + Math.sin(S.eva.heading) * 60);
  }
  updateSteps();
  log(`EVA started on ${S.selected} route — ${S.autopilot ? 'autopilot' : 'manual control (W/A/S/D)'}`, 'ok');
  showAlert(`EVA IN PROGRESS · ${S.selected.toUpperCase()} ROUTE`, true, 2500);
}

function placeAstronaut() {
  const e = S.eva;
  astro.position.copy(groundV(e.pos.x, e.pos.y, 0));
  astro.rotation.y = e.heading;
}

function walkSpeed(x, y) {
  // 與後端 eva.rs 相同的 Tobler 型速度模型（m/s），乘上時間倍率
  const v0 = S.meta.params.walk_speed_mps;
  return v0 * Math.exp(-3.5 * Math.tan((slopeAt(x, y) * Math.PI) / 180)) * TIME_SCALE;
}

function evaTick(dt) {
  const e = S.eva;
  if (!e || e.done) return;
  e.t += (dt * TIME_SCALE) / 60;
  e.o2 = Math.max(0, e.o2 - ((dt * TIME_SCALE) / 60) * e.o2Rate);

  // ---- 控制：自動駕駛（朝導引點）或鍵盤
  let turn = 0, fwd = 0;
  const paused = e.drift || performance.now() < (e.pauseUntil || 0); // 漂移後停下來重新定向
  if (S.autopilot && e.nav && !e.replanning && !paused) {
    const want = Math.atan2(e.nav.next[1] - e.est.y, e.nav.next[0] - e.est.x);
    let d = want - e.heading;
    d = Math.atan2(Math.sin(d), Math.cos(d));
    turn = Math.max(-1, Math.min(1, d * 3));
    fwd = Math.abs(d) < 1.2 ? 1 : 0.2;
  }
  if (keys.has('ArrowLeft')) turn = 1;
  if (keys.has('ArrowRight')) turn = -1;
  if (keys.has('ArrowUp')) fwd = 1;
  if (keys.has('ArrowDown')) fwd = -0.5;
  e.heading += turn * 2.2 * dt;

  const blocked = stepWalker(e.pos, e.heading, fwd, dt) && fwd > 0;
  // ---- 模擬漂移（例如鬆軟沙地滑移、導航錯誤）：1.2 秒內把真實位置推到側邊
  if (e.drift) {
    const k = Math.min(dt / Math.max(e.drift.left, 1e-3), 1);
    const nx = e.pos.x + e.drift.dx * k, ny = e.pos.y + e.drift.dy * k;
    if (!isHazard(nx, ny)) { e.pos.x = nx; e.pos.y = ny; }
    e.drift.dx -= e.drift.dx * k; e.drift.dy -= e.drift.dy * k; e.drift.left -= dt;
    if (e.drift.left <= 0) e.drift = null;
  }
  e.blocked = blocked;
  placeAstronaut();

  // ---- 鏡頭跟隨（俯瞰模式；第一／第三人稱由 followCamera 處理）
  if (S.cam === 'orbit') {
    const delta = astro.position.clone().sub(controls.target);
    controls.target.add(delta);
    camera.position.add(delta);
  }

  // ---- 定位（每 LOC_INTERVAL 秒一次；在 Worker 裡算，不卡畫面）
  e.locTimer += dt;
  if (e.locTimer > LOC_INTERVAL && !e.locBusy) {
    e.locTimer = 0;
    localizeAndTrack();
  }
  updateHud();

  // ---- 抵達判斷
  const end = e.route.path.at(-1);
  if (e.nav && e.nav.remaining_m < 8 && Math.hypot(e.pos.x - end[0], e.pos.y - end[1]) < 15) {
    e.done = true;
    ['rockfall', 'leak', 'drift', 'linkloss'].forEach((id) => ($(id).disabled = true));
    $('home').disabled = !!e.returning; // 採樣完可按「返回基地」規劃回程
    if (e.returning) { log('Crew back at habitat. EVA complete.', 'ok'); showAlert('SAFE RETURN TO HABITAT', true, 5000); }
    else { log('Arrived at science target — begin sampling.', 'ok'); showAlert('TARGET REACHED · BEGIN SAMPLING', true, 5000); }
    feedback.update(performance.now(), { kind: 'none' });
  }
}

async function localizeAndTrack() {
  const e = S.eva;
  e.locBusy = true;
  try {
    const step = [e.pos.x - e.lastLocPos.x, e.pos.y - e.lastLocPos.y];
    e.lastLocPos = { ...e.pos };
    const loc = await api.localize({ true_pos: [e.pos.x, e.pos.y], prev_estimate: [e.est.x, e.est.y], prev_sigma: e.sigma, step_m: step, seed: e.seed++,
      disabled: S.linkLost ? BASE_LINK_IDS : [], extra_beacons: S.deployed.map((d) => d.b) });
    if (S.eva !== e) return;
    e.loc = loc;
    e.est = { x: loc.estimate[0], y: loc.estimate[1] };
    e.sigma = loc.sigma_m;
    drawLocalization(loc);
    if (e.replanning) return;
    const route = e.route;
    const nav = await api.track({ pos: [e.est.x, e.est.y], sigma_m: e.sigma, path: route.path, lookahead_m: 25 });
    if (S.eva !== e || e.done || e.route !== route) return;
    e.nav = nav;
    const now = performance.now();
    if (nav.status === 'replan' && !e.replanning && now - e.lastReplan > 2500) {
      log(`OFF ROUTE ${nav.xte_m.toFixed(0)} m (${nav.reason.replaceAll('_', ' ')}) → auto re-plan from estimated position`, 'warn');
      doReplan('Off route');
    } else if (nav.status === 'off_route' && e.lastStatus !== 'off_route') {
      log(`OFF ROUTE warning: ${nav.xte_m.toFixed(0)} m from the planned path`, 'warn');
    }
    e.lastStatus = nav.status;
  } catch (err) {
    if (err.code !== 'out_of_bounds') log(`Localization error: ${err.message}`, 'bad');
  } finally {
    e.locBusy = false;
  }
}

function drawLocalization(loc) {
  const e = S.eva;
  estMarker.position.copy(groundV(e.est.x, e.est.y, 0.6));
  estDot.position.y = 6;
  estRing.scale.setScalar(Math.max(loc.sigma_m, 1.5));
  estRing.material.color.set(loc.mode === 'multilateration' ? '#4dd6ff' : '#f2c94c');
  const pts = [];
  const me = groundV(e.est.x, e.est.y, 4);
  for (const b of loc.visible_beacons) if (beaconTop[b.id]) pts.push(beaconTop[b.id], me);
  beaconLines.geometry.dispose();
  beaconLines.geometry = new THREE.BufferGeometry().setFromPoints(pts);
}

function updateHud() {
  const e = S.eva, n = e.nav, loc = e.loc, reserve = S.meta.params.o2_reserve_min;
  const capacity = S.meta.params.o2_capacity_min || 1;
  const o2Pct = Math.max(0, Math.min(100, (e.o2 / capacity) * 100));
  $('o2-value').textContent = `${e.o2.toFixed(0)} min`;
  $('o2-pct').textContent = `${o2Pct.toFixed(0)}%`;
  $('o2-fill').style.width = `${o2Pct}%`;
  if (loc) {
    $('m-poserr').textContent = `± ${loc.sigma_m < 10 ? loc.sigma_m.toFixed(1) : loc.sigma_m.toFixed(0)} m`;
    $('m-beacons').textContent = `${loc.visible_beacons.length}`;
  }
  if (!n) return;
  const tRet = n.t_return_min;
  $('m-return').textContent = Number.isFinite(tRet) ? `${tRet.toFixed(0)} min` : '—';
  const mustReturn = !e.returning && Number.isFinite(tRet) && e.o2 < tRet + reserve + 10;
  e.margin = Number.isFinite(tRet) ? e.o2 - tRet - reserve : null; // 還能往外走多久才必須回頭
  if (mustReturn && !e.raisedForReturn) { e.raisedForReturn = true; setTablet(true); }
  const clr = n.clearance_m;
  const terrain = e.blocked ? 'NO-GO ahead' : clr >= 20 ? 'Safe' : clr >= 8 ? `Caution ${clr.toFixed(0)} m` : `Hazard ${clr.toFixed(0)} m`;
  const terrainClass = e.blocked || clr < 8 ? 'bad' : clr < 20 ? 'warn' : 'safe';
  $('m-terrain').textContent = terrain;
  $('m-terrain').className = `metric-val ${terrainClass}`;
  $('g-dist').textContent = `${(n.remaining_m / 1000).toFixed(2)} km`;
  const eta = e.route.eta_min * (n.remaining_m / Math.max(e.route.length_m, 1));
  $('g-time').textContent = `${eta.toFixed(0)} min`;
  $('g-elev').textContent = `${heightAt(e.est.x, e.est.y).toFixed(0)} m`;

  // 狀態列 + 回饋
  const pill = $('status-pill');
  let kind = 'none';
  if (mustReturn) {
    pill.textContent = '⚠ RETURN TO BASE NOW — O₂ AT LIMIT'; pill.className = 'bad'; kind = 'return';
  } else if (e.replanning) {
    pill.textContent = 'RE-PLANNING ON-BOARD…'; pill.className = 'warn';
  } else if (e.blocked || clr < 5) {
    pill.textContent = e.blocked ? 'NO-GO TERRAIN AHEAD' : `HAZARD ${clr.toFixed(0)} m`; pill.className = 'bad'; kind = 'hazard';
  } else if (n.status !== 'on_route') {
    pill.textContent = `OFF ROUTE · ${n.xte_m.toFixed(0)} m`; pill.className = 'warn'; kind = 'offroute';
  } else {
    pill.textContent = e.returning ? 'RETURNING TO BASE · ON ROUTE' : 'ON ROUTE'; pill.className = '';
  }
  feedback.update(performance.now(), { kind, xte: n.xte_m, side: n.side });

  // 指引箭頭：導引點相對於太空人面向的方位
  const bearing = Math.atan2(n.next[1] - e.est.y, n.next[0] - e.est.x);
  let rel = bearing - e.heading;
  rel = Math.atan2(Math.sin(rel), Math.cos(rel));
  $('arrow').style.transform = `rotate(${(-rel * 180) / Math.PI}deg)`;
  $('tb-arrow').style.transform = $('arrow').style.transform;
  const turnTxt = Math.abs(rel) < 0.2 ? 'straight ahead' : rel > 0 ? `turn left ${Math.round((rel * 180) / Math.PI)}°` : `turn right ${Math.round((-rel * 180) / Math.PI)}°`;
  $('compass-text').innerHTML = `${turnTxt}<br><small>${(n.remaining_m / 1000).toFixed(2)} km to ${e.returning ? 'base' : 'target'}</small>`;
}

async function doReplan(reasonText) {
  const e = S.eva;
  e.replanning = true;
  e.lastReplan = performance.now();
  const t0 = performance.now();
  try {
    const res = await api.replan({ pos: [e.est.x, e.est.y], goal: [S.goal.x, S.goal.y], mode: e.mode, obstacles: S.obstacles, o2_min: e.o2 });
    const ms = (performance.now() - t0).toFixed(0);
    if (S.eva !== e) return;
    if (res.must_return && res.return_route) {
      setActiveRoute(res.return_route, 'return');
      e.returning = true;
      const why = res.reason === 'goal_beyond_pnr' ? `round trip ${res.round_trip_min?.toFixed(0)} min exceeds O₂ budget` : 'no safe path to target';
      log(`${reasonText}: ${why} → RETURN TO BASE (computed on-board in ${ms} ms)`, 'bad');
      showAlert('BEYOND POINT OF NO RETURN · RETURN TO BASE', false, 5000);
      $('rockfall').disabled = true;
    } else if (res.route) {
      setActiveRoute(res.route, e.routeKey === 'return' ? 'safe' : e.routeKey);
      log(`${reasonText}: new route computed on-board in ${ms} ms (${res.route.eta_min.toFixed(0)} min to target)`, 'warn');
      showAlert('NEW ROUTE COMPUTED ON-BOARD', false, 3000);
    }
    e.nav = null;
    if (pnrOn()) applyLayers();
  } catch (err) {
    log(`Re-plan failed: ${err.message}`, 'bad');
  } finally {
    e.replanning = false;
  }
}

async function returnHome() {
  const e = S.eva;
  if (!e || e.returning) return;
  if (e.done) { e.est = { ...e.pos }; e.lastLocPos = { ...e.pos }; e.done = false; e.heading = S.walk.heading; }
  try {
    const r = await api.route({ start: [e.est.x, e.est.y], goal: S.meta.base, mode: 'safe' });
    setActiveRoute(r, 'return');
    e.returning = true;
    e.nav = null;
    log(`Return to base selected: ${(r.length_m / 1000).toFixed(2)} km, ${r.eta_min.toFixed(0)} min`, 'warn');
    showAlert('RETURNING TO BASE', true, 2500);
  } catch (err) {
    log(`Return route failed: ${err.message}`, 'bad');
  }
}

function pointAlong(path, d) {
  let acc = 0;
  for (let i = 1; i < path.length; i++) {
    const l = Math.hypot(path[i][0] - path[i - 1][0], path[i][1] - path[i - 1][1]);
    if (acc + l >= d) { const t = (d - acc) / (l || 1); return [path[i - 1][0] + (path[i][0] - path[i - 1][0]) * t, path[i - 1][1] + (path[i][1] - path[i - 1][1]) * t]; }
    acc += l;
  }
  return path.at(-1);
}
function rockfall() {
  const e = S.eva;
  if (!e || e.returning || !e.nav) return;
  if (e.nav.remaining_m < 120) return log('Too close to the target to place a rockfall', 'warn');
  const p = pointAlong(e.route.path, e.nav.along_m + Math.min(150, e.nav.remaining_m * 0.5));
  const o = { x: p[0], y: p[1], r: 30 };
  S.obstacles.push(o);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(o.r, o.r, 12, 24), new THREE.MeshBasicMaterial({ color: '#ff2a2a', transparent: true, opacity: 0.4 }));
  m.position.copy(groundV(o.x, o.y, 6));
  obstacleGroup.add(m);
  doReplan('Rockfall reported ahead');
}
function drift() {
  const e = S.eva;
  if (!e || !e.nav) return;
  // 往路線的垂直方向推 40 m（選不會撞進危險區的那一側）
  const a = pointAlong(e.route.path, e.nav.along_m), b = pointAlong(e.route.path, e.nav.along_m + 5);
  const len = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1;
  const nx = -(b[1] - a[1]) / len, ny = (b[0] - a[0]) / len;
  const side = isHazard(e.pos.x + nx * 45, e.pos.y + ny * 45) ? -1 : 1;
  e.drift = { dx: nx * 45 * side, dy: ny * 45 * side, left: 1.2 };
  e.pauseUntil = performance.now() + 3200;
  log('Simulated drift: crew pushed ~45 m sideways (true position) and stops to re-orient', 'warn');
}
function leak() {
  const e = S.eva;
  if (!e) return;
  e.o2 = Math.min(e.o2, 40);
  e.o2Rate = 3;
  $('leak').disabled = true;
  log('Suit O₂ leak detected: 40 min left, consumption ×3', 'bad');
  refreshPnrBoundary(true);
  doReplan('O₂ leak');
}
// ---- 通訊中斷與自行布設信標
const BASE_LINK_IDS = ['hab', 'rover', 'relay']; // 基地網路（LoRa 長距離）
const BEACON_KIT = 4; // 每次 EVA 隨身攜帶的 UWB 信標數
function setBeaconDim(id, dim) { const m = beaconTopMesh[id]; if (m) m.material.color.set(dim ? '#555a60' : '#ff9f43'); }
function linkLoss() {
  if (!S.eva || S.linkLost) return;
  S.linkLost = true;
  BASE_LINK_IDS.forEach((id) => setBeaconDim(id, true));
  $('linkloss').disabled = true;
  log('Base link lost: habitat, rover and relay beacons silent → only UWB beacons left; deploy beacons to keep a position fix', 'bad');
  showAlert('LINK TO BASE LOST · DEPLOY BEACONS', false, 4000);
}
function deployBeacon() {
  const e = S.eva;
  if (!e || S.deployed.length >= BEACON_KIT) return;
  const last = S.deployed.at(-1)?.b;
  if (last && Math.hypot(e.pos.x - last.x, e.pos.y - last.y) < 15) {
    log('Too close to the last beacon — walk at least 15 m apart so the beacons spread out', 'warn');
    return;
  }
  const n = S.deployed.length + 1;
  // 信標放在太空人腳下；位置以「放下當下的估計位置」記錄（實務上會用多點定位或回基地後再校正）
  const b = { id: `drop${n}`, kind: 'uwb', x: e.pos.x, y: e.pos.y, label: `Deployed #${n}` };
  S.deployed.push({ b, obj: addBeaconMarker(b, '#7dffb0') });
  $('deploy').textContent = `📍 Deploy beacon (${BEACON_KIT - S.deployed.length} left)`;
  if (S.deployed.length >= BEACON_KIT) $('deploy').disabled = true;
  log(`Beacon #${n} deployed at (${b.x.toFixed(0)}, ${b.y.toFixed(0)}) m — ${BEACON_KIT - S.deployed.length} left in kit`, 'ok');
  e.locTimer = 1e9; // 立刻重新定位
}
function clearBeaconEvents() {
  S.linkLost = false;
  BASE_LINK_IDS.forEach((id) => setBeaconDim(id, false));
  for (const d of S.deployed) {
    if (d.obj.userData.siteLabel) { siteLabels.delete(d.obj.userData.siteLabel); scene.remove(d.obj.userData.siteLabel); d.obj.userData.siteLabel.element.remove(); }
    d.obj.traverse((o) => o.element?.remove());
    scene.remove(d.obj);
    delete beaconTop[d.b.id]; delete beaconTopMesh[d.b.id];
  }
  S.deployed = [];
  $('deploy').textContent = `📍 Deploy beacon (${BEACON_KIT} left)`;
}

function reset() {
  S.eva = null;
  clearPnrBoundary();
  clearBeaconEvents();
  S.obstacles = [];
  keys.clear();
  obstacleGroup.children.slice().forEach((m) => obstacleGroup.remove(m));
  estMarker.visible = false;
  initWalker();
  beaconLines.geometry = new THREE.BufferGeometry();
  applyFog();
  clearRoutes();
  $('routes').innerHTML = '';
  $('hud').classList.add('hidden');
  $('plan').disabled = false;
  ['start', 'rockfall', 'leak', 'drift', 'home', 'linkloss', 'deploy'].forEach((id) => ($(id).disabled = true));
  overviewCamera();
  if (pnrOn()) applyLayers();
  S.selected = null;
  updateSteps();
  log('Reset');
}

// ---------------------------------------------------------------- UI helpers
function log(msg, cls = '') {
  const div = document.createElement('div');
  div.className = cls;
  div.textContent = (S.eva ? `[T+${S.eva.t.toFixed(0)}] ` : '') + msg;
  $('log').prepend(div);
}
let alertTimer;
function showAlert(text, info, ms) {
  if (!info) setTablet(true); // 緊急狀況：平板自動舉起
  const a = $('alert');
  a.textContent = text;
  // 展開平板時，提示移到頂欄下方的地圖範圍，避免覆蓋品牌與任務狀態。
  a.className = `${info ? 'info' : ''}${S.tabletUp ? ' tablet-alert' : ''}`.trim();
  clearTimeout(alertTimer);
  alertTimer = setTimeout(() => a.classList.add('hidden'), ms);
}
// ---------------------------------------------------------------- 2D map mode (ported from teammate's version)
function createMapCamera() {
  const aspect = innerWidth / innerHeight;
  mapCamera = new THREE.OrthographicCamera(-mapViewExtent * aspect, mapViewExtent * aspect, mapViewExtent, -mapViewExtent, 0.0001, 100000);
  mapCamera.up.set(0, 0, -1);
  mapControls = new OrbitControls(mapCamera, renderer.domElement);
  Object.assign(mapControls, { enableDamping: true, enableRotate: false, screenSpacePanning: true, minZoom: 0.75, maxZoom: 100000, zoomToCursor: true });
  mapControls.mouseButtons.LEFT = THREE.MOUSE.PAN;
  mapControls.touches.ONE = THREE.TOUCH.PAN;
  mapControls.enabled = false;
  fitMapCamera();
}
const mapIsGlobal = () => S.mapExtent === 'global' && S.hasGlobalMap;
const mapIsRegional = () => S.mapExtent === 'regional' && S.hasGlobalMap;
function mapExtentInfo() {
  if (S.mapExtent === 'global' && S.global) return { width: 360, height: 180, centerX: 0, centerZ: 0 };
  if (S.mapExtent === 'regional' && S.regional) {
    const b = S.regional.meta.georeference;
    return { width: b.longitude_bounds_deg[1] - b.longitude_bounds_deg[0], height: b.latitude_bounds_deg[1] - b.latitude_bounds_deg[0], centerX: (b.longitude_bounds_deg[0] + b.longitude_bounds_deg[1]) / 2 - 180, centerZ: -(b.latitude_bounds_deg[0] + b.latitude_bounds_deg[1]) / 2 };
  }
  const b = localGeoBounds();
  return { width: b.east - b.west, height: b.north - b.south, centerX: (b.west + b.east) / 2 - 180, centerZ: -(b.south + b.north) / 2 };
}
function fitMapCamera() {
  if (!mapCamera) return;
  const aspect = innerWidth / innerHeight;
  const { width, height } = mapExtentInfo();
  mapViewExtent = Math.max(height / 2, width / (2 * aspect)) * 1.08;
  Object.assign(mapCamera, { left: -mapViewExtent * aspect, right: mapViewExtent * aspect, top: mapViewExtent, bottom: -mapViewExtent });
  mapCamera.updateProjectionMatrix();
}
function mapCenter() {
  const { centerX, centerZ } = mapExtentInfo();
  return new THREE.Vector3(centerX, 0, centerZ);
}
function syncMapVisibility() {
  const isMap = S.view === '2d';
  terrainMesh.visible = !isMap;
  mapMesh.visible = isMap;
  globalMapMeshes.forEach((m) => (m.visible = isMap));
  if (regionalMesh) regionalMesh.visible = isMap;
  syncMapPatternVisibility();
  // 現場標記：全球圖用大圓點、區域圖縮小；看現場 HiRISE 圖時隱藏，避免蓋住地圖
  if (S.sitePin) {
    S.sitePin.visible = isMap && S.mapExtent !== 'local';
    S.sitePin.scale.setScalar(S.mapExtent === 'regional' ? 0.25 : 1);
  }
  if (rockMesh) rockMesh.visible = !isMap;
  astro.visible = !isMap && S.cam !== 'first';
  estMarker.visible = !isMap && !!S.eva;
  beaconLines.visible = !isMap;
  obstacleGroup.visible = !isMap;
  routeGroup.visible = !isMap;
  if (S.region) S.region.mesh.visible = !isMap && !S.inGlobe && VIEW_KM[+$('view-dist').value] > 3;
  labels.domElement.style.visibility = isMap ? 'hidden' : '';
  // 2D 相機離地很遠，霧會把整張圖蓋掉 → 2D 模式關閉霧
  applyFog();
}
function setViewMode(mode) {
  if (S.inGlobe) toggleGlobe();
  S.view = mode === '2d' ? '2d' : '3d';
  const isMap = S.view === '2d';
  if (isMap && !mapCamera) createMapCamera();
  camera = isMap ? mapCamera : perspectiveCamera;
  controls = isMap ? mapControls : perspectiveControls;
  perspectiveControls.enabled = !isMap && S.cam === 'orbit';
  if (mapControls) mapControls.enabled = isMap;
  ['view-3d', 'view-2d'].forEach((id) => {
    const on = (id === 'view-2d') === isMap;
    $(id).classList.toggle('active', on);
    $(id).setAttribute('aria-pressed', String(on));
  });
  $('view-hint').textContent = isMap ? (mapIsGlobal() ? 'Drag to pan · wheel to zoom · east/west wraps' : 'Drag to pan · wheel to zoom · north is up') : 'Drag to orbit · wheel to zoom';
  if (isMap) fitMapCamera();
  syncMapVisibility();
  overviewCamera();
}
async function setMapExtent(extent) {
  if (extent === 'global' && !S.hasGlobalMap) {
    try { await buildGlobalMap(); } catch (e) { log(`Global map unavailable: ${e.message}`, 'warn'); }
  }
  if (extent === 'regional' && !regionalMesh) {
    try { await buildRegionalMap(); } catch (e) { log(`Regional map unavailable: ${e.message}`, 'warn'); }
  }
  S.mapExtent = extent !== 'local' && S.hasGlobalMap ? extent : 'local';
  const g = S.mapExtent === 'global';
  ['extent-global', 'extent-regional', 'extent-local'].forEach((id) => {
    const on = id === `extent-${S.mapExtent}`;
    $(id).classList.toggle('active', on);
    $(id).setAttribute('aria-pressed', String(on));
  });
  if (S.view !== '2d') setViewMode('2d');
  else { fitMapCamera(); syncMapVisibility(); overviewCamera(); }
  $('view-hint').textContent = g ? 'Drag to pan · wheel to zoom · east/west wraps' : S.mapExtent === 'regional' ? 'Drag to pan · wheel to zoom · Gale MOC context' : 'Drag to pan · wheel to zoom · north is up';
}
/** 全球 2D 地圖東西向無縫循環。 */
function wrapGlobalMap() {
  if (S.view !== '2d' || !mapIsGlobal()) return;
  const shift = Math.floor((mapControls.target.x + 180) / 360) * 360;
  if (!shift) return;
  mapControls.target.x -= shift;
  mapCamera.position.x -= shift;
}

function overviewCamera() {
  if (S.view === '2d' && mapCamera) {
    const c = mapCenter();
    mapControls.target.copy(c);
    mapCamera.position.set(c.x, 1000, c.z);
    mapCamera.zoom = 1;
    mapCamera.updateProjectionMatrix();
    mapCamera.lookAt(c);
    mapControls.update();
    return;
  }
  if (S.cam !== 'orbit') return;
  const shift = 0;
  perspectiveCamera.position.set(shift - S.W * 0.05, S.W * 0.78, S.H * 0.9);
  perspectiveControls.target.set(shift, 0, -S.H * 0.04);
  perspectiveControls.update();
}

let down = null;
renderer.domElement.addEventListener('pointerdown', (e) => (down = [e.clientX, e.clientY]));
renderer.domElement.addEventListener('pointerup', (e) => {
  if (!down || Math.hypot(e.clientX - down[0], e.clientY - down[1]) > 5 || S.eva || S.mapExtent !== 'local') return;
  if (S.view === '3d' && S.cam !== 'orbit') return;
  const ray = new THREE.Raycaster();
  ray.setFromCamera(new THREE.Vector2((e.clientX / innerWidth) * 2 - 1, -(e.clientY / innerHeight) * 2 + 1), camera);
  const hit = ray.intersectObject(S.view === '2d' ? mapMesh : terrainMesh)[0];
  if (!hit) return;
  const p = S.view === '2d' ? (() => {
    const b = localGeoBounds();
    return {
      x: ((hit.point.x + 180 - b.west) / (b.east - b.west)) * S.W,
      y: ((-hit.point.z - b.south) / (b.north - b.south)) * S.H,
    };
  })() : fromV(hit.point);
  setCustomGoal(p);
});
function setCustomGoal(p) {
  $('target').value = 'custom';
  $('target-desc').textContent = `Custom goal at (${p.x.toFixed(0)}, ${p.y.toFixed(0)}) m`;
  setGoal(p.x, p.y, `custom point (${p.x.toFixed(0)}, ${p.y.toFixed(0)}) m`);
}

// ---------------------------------------------------------------- explorer: walker, camera, handheld tablet
// 畫面只有火星和太空人；系統介面是太空人手上的平板（Tab / M 舉起）。

/** 太空人站到基地旁邊（圓頂外、非危險區）；EVA 前後都能自由走動。 */
function initWalker() {
  const [bx, by] = S.meta.base;
  let pos = { x: bx, y: by };
  for (let k = 0; k < 16; k++) {
    const a = (k / 16) * Math.PI * 2, x = bx + Math.cos(a) * 24, y = by + Math.sin(a) * 24;
    if (!isHazard(x, y)) { pos = { x, y }; break; }
  }
  const g = S.goal || { x: S.W / 2, y: S.H / 2 };
  S.walk = { pos, heading: Math.atan2(g.y - pos.y, g.x - pos.x), blocked: false };
  S.look = { yaw: 0, pitch: 0 };
  astro.position.copy(groundV(pos.x, pos.y, 0));
  astro.rotation.y = S.walk.heading;
  astro.visible = S.view === '3d' && S.cam !== 'first';
}

/**
 * 往前走一步。正前方是禁止通行區時，左右各試 30°、60° 沿著邊緣滑開，不會卡死；
 * 已經站在危險格上（例如被漂移推進去）時允許走出來。回傳「正前方是否被擋」。
 */
function stepWalker(p, heading, fwd, dt) {
  if (!fwd) return false;
  const v = walkSpeed(p.x, p.y) * fwd * dt;
  const stuck = isHazard(p.x, p.y);
  const inside = (x, y) => x > 1 && y > 1 && x < S.W - 1 && y < S.H - 1;
  let straight = true;
  for (const da of [0, 0.5, -0.5, 1.0, -1.0]) {
    const a = heading + da, k = da ? 0.8 : 1;
    const nx = p.x + Math.cos(a) * v * k, ny = p.y + Math.sin(a) * v * k;
    if (inside(nx, ny) && (stuck || !isHazard(nx, ny))) { p.x = nx; p.y = ny; return !straight; }
    straight = false;
  }
  return true;
}

/** EVA 以外的自由走動（W/A/S/D、方向鍵、手機方向鍵）。 */
function walkTick(dt) {
  const w = S.walk;
  if (!w || S.view !== '3d' || S.inGlobe) return;
  let turn = 0, fwd = 0;
  if (keys.has('ArrowLeft')) turn = 1;
  if (keys.has('ArrowRight')) turn = -1;
  if (keys.has('ArrowUp')) fwd = 1;
  if (keys.has('ArrowDown')) fwd = -0.5;
  w.heading += turn * 2.2 * dt;
  w.blocked = stepWalker(w.pos, w.heading, fwd, dt) && fwd > 0;
  astro.position.copy(groundV(w.pos.x, w.pos.y, 0));
  astro.rotation.y = w.heading;
}

/** 第一人稱：眼睛高度看向前方；第三人稱：跟在背後、不鑽進地形。拖曳可以轉頭。 */
const _eye = new THREE.Vector3(), _want = new THREE.Vector3();
function followCamera(dt) {
  if (!S.walk) return;
  if (S.eva || keys.has('ArrowUp')) S.look.yaw *= Math.exp(-dt * 1.5); // 走路時視線慢慢回到正前方
  const h = S.walk.heading + S.look.yaw, fx = Math.cos(h), fz = -Math.sin(h);
  const b = astro.position;
  if (S.cam === 'first') {
    _eye.set(b.x, b.y + 4.4, b.z);
    camera.position.copy(_eye);
    const pitch = -0.1 + S.look.pitch;
    camera.lookAt(_eye.x + fx * Math.cos(pitch) * 20, _eye.y + Math.sin(pitch) * 20, _eye.z + fz * Math.cos(pitch) * 20);
    return;
  }
  const dist = 34, height = 14 - S.look.pitch * 40;
  _want.set(b.x - fx * dist, b.y + height, b.z - fz * dist);
  const g = fromV(_want), ground = groundV(g.x, g.y, 4).y;
  if (_want.y < ground) _want.y = ground;
  camera.position.lerp(_want, 1 - Math.exp(-dt * 6));
  camera.lookAt(b.x, b.y + 4, b.z);
}

let lookPtr = null;
renderer.domElement.addEventListener('pointerdown', (e) => (lookPtr = [e.clientX, e.clientY]));
addEventListener('pointerup', () => (lookPtr = null));
renderer.domElement.addEventListener('pointermove', (e) => {
  if (!lookPtr || S.view !== '3d' || S.inGlobe || S.cam === 'orbit') return;
  const dx = e.clientX - lookPtr[0], dy = e.clientY - lookPtr[1];
  lookPtr = [e.clientX, e.clientY];
  S.look.yaw -= dx * 0.006;
  S.look.pitch = Math.max(-0.6, Math.min(0.6, S.look.pitch - dy * 0.004));
});

function setCam(mode) {
  S.cam = mode;
  S.look = { yaw: 0, pitch: 0 };
  perspectiveCamera.layers.set(0);
  perspectiveCamera.layers.enable(mode === 'first' ? 2 : 3);
  ['third', 'first', 'orbit'].forEach((m) => $(`cam-${m}`).classList.toggle('active', m === mode));
  if (S.view === '3d' && !S.inGlobe) {
    perspectiveControls.enabled = mode === 'orbit';
    astro.visible = mode !== 'first';
    if (mode === 'orbit') {
      if (S.eva) {
        const p = astro.position;
        controls.target.copy(p);
        camera.position.set(p.x - 300, p.y + 400, p.z + 500);
      } else overviewCamera();
    }
  }
  applyFog();
  $('cam-hint').classList.toggle('hidden', mode === 'orbit');
}

function setTablet(up) {
  S.tabletUp = up;
  const t = $('tablet');
  t.classList.toggle('raised', up);
  t.classList.toggle('lowered', !up);
  const alert = $('alert');
  if (!alert.classList.contains('hidden')) alert.classList.toggle('tablet-alert', up);
  if (!up) closeMore();
  if (!up && document.activeElement && t.contains(document.activeElement)) document.activeElement.blur();
  if (up && S.eva) $('step3').scrollIntoView({ block: 'start' }); // EVA 中：直接看到緊急按鈕
  keys.clear();
  tourEvent('tablet');
}

// ---- 平板上的小地圖：同一個 3D 場景，用正上方的正交相機畫在平板的地圖區（north up）
const miniCam = new THREE.OrthographicCamera(-1, 1, 1, -1, 1, 50000);
miniCam.up.set(0, 0, -1);
miniCam.layers.enable(1);
const MINI_BG = new THREE.Color('#14100d');
const flat = (g) => { g.rotateX(-Math.PI / 2); return g; };
function miniMarker(geo, color) {
  const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color, depthTest: false, transparent: true }));
  m.layers.set(1);
  m.renderOrder = 1000;
  scene.add(m);
  return m;
}
const miniMe = miniMarker(flat(new THREE.ShapeGeometry(new THREE.Shape([
  new THREE.Vector2(0, 1), new THREE.Vector2(0.65, -0.75), new THREE.Vector2(0, -0.4), new THREE.Vector2(-0.65, -0.75),
]))), '#ffffff');
const miniGoal = miniMarker(flat(new THREE.RingGeometry(0.55, 1, 24)), '#ff7a3d');
const miniBase = miniMarker(flat(new THREE.PlaneGeometry(1.4, 1.4)), '#3fd17a');
const miniDefaultHalf = () => (S.eva ? 350 : Math.max(S.W, S.H) * 0.55);
let miniPan = { x: 0, z: 0 };

function renderMini() {
  if (!S.tabletUp || S.view !== '3d' || S.inGlobe || !S.walk || !terrainMesh) return;
  const r = $('tab-map').getBoundingClientRect();
  if (r.width < 20 || r.height < 20) return;
  const follow = S.eva || S.miniHalf !== null;
  const half = S.miniHalf ?? miniDefaultHalf();
  const c = (follow ? astro.position : toV(S.W / 2, S.H / 2, S.zmid)).clone();
  c.x += miniPan.x; c.z += miniPan.z;
  const aspect = r.width / r.height;
  Object.assign(miniCam, { left: -half * aspect, right: half * aspect, top: half, bottom: -half });
  miniCam.updateProjectionMatrix();
  miniCam.position.set(c.x, 20000, c.z);
  miniCam.lookAt(c.x, 0, c.z);
  const k = half * 0.045;
  miniMe.position.set(astro.position.x, astro.position.y + 50, astro.position.z);
  miniMe.rotation.y = S.walk.heading - Math.PI / 2;
  miniMe.scale.setScalar(k);
  miniGoal.visible = !!S.goal;
  if (S.goal) { miniGoal.position.copy(groundV(S.goal.x, S.goal.y, 50)); miniGoal.scale.setScalar(k * 0.9); }
  miniBase.position.copy(groundV(S.meta.base[0], S.meta.base[1], 50));
  miniBase.scale.setScalar(k * 0.8);
  const fog = scene.fog, bg = scene.background;
  scene.fog = null;
  scene.background = MINI_BG;
  const y = host.clientHeight - r.bottom;
  renderer.setScissorTest(true);
  renderer.setScissor(r.left, y, r.width, r.height);
  renderer.setViewport(r.left, y, r.width, r.height);
  renderer.render(scene, miniCam);
  renderer.setScissorTest(false);
  renderer.setViewport(0, 0, host.clientWidth, host.clientHeight);
  scene.fog = fog;
  scene.background = bg;
}

const tabMap = $('tab-map');
let mapDown = null, mapPanPointer = null;
tabMap.addEventListener('pointerdown', (e) => {
  if (e.target.closest('button')) return;
  if (e.button === 1) {
    e.preventDefault();
    mapPanPointer = { id: e.pointerId, x: e.clientX, y: e.clientY };
    tabMap.setPointerCapture(e.pointerId);
    tabMap.classList.add('panning');
  } else if (e.button === 0) mapDown = [e.clientX, e.clientY];
});
tabMap.addEventListener('pointermove', (e) => {
  if (!mapPanPointer || e.pointerId !== mapPanPointer.id) return;
  const r = tabMap.getBoundingClientRect();
  const scale = 2 * (S.miniHalf ?? miniDefaultHalf()) / r.height;
  miniPan.x -= (e.clientX - mapPanPointer.x) * scale;
  miniPan.z -= (e.clientY - mapPanPointer.y) * scale;
  mapPanPointer.x = e.clientX; mapPanPointer.y = e.clientY;
});
tabMap.addEventListener('pointerup', (e) => {
  if (mapPanPointer && e.pointerId === mapPanPointer.id) { mapPanPointer = null; tabMap.classList.remove('panning'); return; }
  if (e.button !== 0) return;
  if (!mapDown || Math.hypot(e.clientX - mapDown[0], e.clientY - mapDown[1]) > 5 || S.eva) return;
  const r = tabMap.getBoundingClientRect();
  const ray = new THREE.Raycaster();
  ray.setFromCamera(new THREE.Vector2(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1), miniCam);
  const hit = ray.intersectObject(terrainMesh)[0];
  if (hit) setCustomGoal(fromV(hit.point));
});
tabMap.addEventListener('wheel', (e) => {
  e.preventDefault();
  const cur = S.miniHalf ?? miniDefaultHalf();
  S.miniHalf = Math.max(60, Math.min(Math.max(S.W, S.H) * 0.8, cur * (e.deltaY > 0 ? 1.2 : 1 / 1.2)));
}, { passive: false });
tabMap.addEventListener('pointercancel', () => { mapPanPointer = null; tabMap.classList.remove('panning'); });
tabMap.addEventListener('auxclick', (e) => { if (e.button === 1) e.preventDefault(); });
tabMap.addEventListener('dblclick', () => { S.miniHalf = null; miniPan = { x: 0, z: 0 }; });

// ---- 平板閒置畫面：指南針 + 環境危險程度（顏色）+ 導航狀態
let tabTimer = 0;
const DIR8 = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
function updateTabBar(dt) {
  tabTimer += dt;
  if (tabTimer < 0.12 || !S.walk) return;
  tabTimer = 0;
  const w = S.walk, e = S.eva;
  const bearing = (((90 - (w.heading * 180) / Math.PI) % 360) + 360) % 360;
  $('tb-ring').style.transform = `rotate(${-bearing}deg)`;
  $('tb-heading').textContent = `${String(Math.round(bearing) % 360).padStart(3, '0')}° ${DIR8[Math.round(bearing / 45) % 8]}`;
  $('sim-heading').textContent = $('tb-heading').textContent;
  // 腳下坡度 + 最近的禁止通行區（坡度 > 門檻或太粗糙）有多近
  const p = w.pos;
  let near = isHazard(p.x, p.y) ? 0 : Infinity;
  for (const d of [5, 10, 20, 35]) {
    if (near !== Infinity) break;
    for (let k = 0; k < 12; k++) {
      const a = (k / 12) * Math.PI * 2;
      if (isHazard(p.x + Math.cos(a) * d, p.y + Math.sin(a) * d)) { near = d; break; }
    }
  }
  const slope = slopeAt(p.x, p.y), blocked = e ? e.blocked : w.blocked;
  const lvl = near <= 5 || blocked ? 'high' : near <= 20 || slope > 15 ? 'mid' : 'low';
  const hz = $('tb-hazard');
  hz.className = `tb-hazard ${lvl}`;
  const hazardText = lvl === 'high' ? (near === 0 ? 'NO-GO' : 'HIGH') : lvl === 'mid' ? 'CAUTION' : 'LOW';
  $('tb-haz-text').textContent = hazardText;
  hz.title = `slope ${slope.toFixed(0)}° · nearest no-go ${Number.isFinite(near) ? `≤ ${near} m` : '> 35 m'}`;
  const simHazard = $('sim-hazard');
  simHazard.className = `sim-status terrain ${lvl}`;
  $('sim-hazard-text').textContent = `TERRAIN: ${hazardText}`;
  const position = e ? e.est : w.pos;
  $('sim-position').textContent = `(${position.x.toFixed(0)}, ${position.y.toFixed(0)}) m`;
  const terrain = lvl === 'low' ? 'Low Risk' : lvl === 'mid' ? 'Caution' : 'High Risk';
  const terrainValue = $('sim-terrain');
  terrainValue.textContent = terrain;
  terrainValue.className = lvl;
  if (e) {
    $('tb-arrow').classList.remove('hidden');
    // 回頭倒數：剩餘 O₂ − 回程時間 − 安全預留
    const pn = $('tb-pnr'), m = e.margin;
    pn.classList.remove('hidden');
    if (e.returning) { pn.className = 'tb-pnr ret'; $('tb-pnr-text').textContent = 'HEADING HOME'; }
    else if (m == null) { pn.className = 'tb-pnr'; $('tb-pnr-text').textContent = '—'; }
    else {
      pn.className = `tb-pnr ${m <= 10 ? 'high' : m <= 45 ? 'mid' : 'low'}`;
      $('tb-pnr-text').textContent = m <= 0 ? 'TURN BACK NOW' : `${m.toFixed(0)} min`;
    }
    $('m-turnback').textContent = e.returning ? '—' : m == null ? '—' : m <= 0 ? 'NOW' : `${m.toFixed(0)} min`;
  } else {
    $('tb-pnr').classList.add('hidden');
    $('tb-arrow').classList.add('hidden');
  }
}

// ---------------------------------------------------------------- 不歸點邊界（EVA 中自動顯示）
// 紅點連成的圈：圈內 = 從目前位置走過去還能用剩餘 O₂ 安全回基地；氧氣越少圈越小。
const pnrPts = new THREE.Points(new THREE.BufferGeometry(), new THREE.PointsMaterial({ color: '#ff3b30', size: 4, sizeAttenuation: false, depthTest: false, transparent: true, opacity: 0.9 }));
pnrPts.renderOrder = 950;
pnrPts.layers.enable(1); // 主畫面＋平板小地圖都看得到
scene.add(pnrPts);
let pnrBusy = false, pnrLast = -1e9;
async function refreshPnrBoundary(force = false) {
  const e = S.eva;
  if (!e || e.done || pnrBusy || S.view !== '3d') return;
  const now = performance.now();
  if (!force && now - pnrLast < 4000) return;
  pnrBusy = true; pnrLast = now;
  try {
    const g = await api.layer('pnr', { step: MESH_STEP, x: e.est.x, y: e.est.y, o2_min: e.o2 });
    if (S.eva !== e) return;
    const { w, h, data } = g, cs = (S.meta.width * S.meta.cell_m) / w, pts = [];
    let inside = 0;
    for (let j = 1; j < h - 1; j++) for (let i = 1; i < w - 1; i++) {
      const k = j * w + i;
      if (data[k] < 128) continue;
      inside++;
      // 邊界 = 旁邊那格「可以走、但走過去就回不來」；旁邊是禁區（本來就不能走）的不算
      const x = (i + 0.5) * cs, y = (j + 0.5) * cs;
      for (const [di, dj] of [[-1, 0], [1, 0], [0, -1], [0, 1]]) {
        if (data[k + di + dj * w] >= 128) continue;
        const nx = x + di * cs, ny = y + dj * cs;
        let open = true;
        for (const [ox, oy] of [[0, 0], [-0.4, -0.4], [0.4, -0.4], [-0.4, 0.4], [0.4, 0.4]]) if (isHazard(nx + ox * cs, ny + oy * cs)) { open = false; break; }
        if (open) { pts.push(groundV(x, y, 3)); break; }
      }
    }
    e.pnrInside = inside / ((w - 2) * (h - 2));
    if (e.margin != null && e.margin > 120) pts.length = 0; // O₂ 很充裕時整個區域都回得來，不畫線
    pnrPts.geometry.dispose();
    pnrPts.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  } catch (err) { /* 圖層失敗不影響 EVA */ } finally { pnrBusy = false; }
}
function clearPnrBoundary() { pnrPts.geometry.dispose(); pnrPts.geometry = new THREE.BufferGeometry(); }

// ---------------------------------------------------------------- boot
async function boot() {
  const t0 = performance.now();
  const params = new URLSearchParams(location.search);
  const siteDir = params.get('site') === 'nw' ? 'data/site_nw/' : 'data/site/';
  const info = await api.ready({ siteBase: new URL(siteDir, location.href).href, synthetic: params.has('synthetic') });
  const build_ms = info.build_ms;
  S.geo = info.geo || null;
  $('loading-text').textContent = 'Loading terrain…';
  S.meta = await api.meta();
  [S.terr, S.hazard, S.slope, S.rough] = await Promise.all([
    api.terrain(MESH_STEP), api.layer('hazard', { step: 1 }), api.layer('slope', { step: 1 }), api.layer('rough', { step: 1 }),
  ]);
  S.W = S.meta.width * S.meta.cell_m;
  S.H = S.meta.height * S.meta.cell_m;
  S.zmid = (S.meta.z_min + S.meta.z_max) / 2;
  S.global = api.globalMap ? await api.globalMap() : null;
  S.regional = api.regionalMap ? await api.regionalMap() : null;
  buildTerrain();
  try { await buildGlobalMap(); } catch (e) { log(`Global map unavailable: ${e.message}`, 'warn'); }
  try { await buildRegionalMap(); } catch (e) { log(`Regional map unavailable: ${e.message}`, 'warn'); }
  scatterRocks();
  addMarkers();
  overviewCamera();
  buildLayerPanel();
  applyLayers().catch((e) => log(`Default hazard layer unavailable: ${e.message}`, 'warn'));
  if (S.geo) {
    try {
      S.region = await buildRegion(S.geo, toV, S.W, S.H);
      scene.add(S.region.mesh);
    } catch (e) { log(`Regional map unavailable: ${e.message}`, 'warn'); }
  }
  if (info.source === 'hirise' && params.get('site') !== 'nw') loadOrthophoto().catch((e) => log(`Orthophoto unavailable (${e.message})`, 'warn'));
  $('view-3d').onclick = () => setViewMode('3d');
  $('view-2d').onclick = () => setViewMode('2d');
  $('extent-global').onclick = () => setMapExtent('global');
  $('extent-regional').onclick = () => setMapExtent('regional');
  $('extent-local').onclick = () => setMapExtent('local');
  $('view-dist').oninput = (e) => setViewDistance(+e.target.value);
  setViewDistance(+$('view-dist').value);
  $('globe').onclick = () => toggleGlobe().catch((e) => log(`Globe failed: ${e.message}`, 'bad'));

  const sel = $('target');
  sel.add(new Option('Choose a science target', ''));
  for (const t of S.meta.targets) sel.add(new Option(`${t.name} (science ${t.science})`, t.id));
  sel.add(new Option('Custom (click map)', 'custom'));
  const pick = () => {
    const t = S.meta.targets.find((x) => x.id === sel.value);
    if (sel.value === 'custom') {
      S.pickingCustom = true;
      $('target-desc').textContent = 'Click a safe point on the map to set a custom destination.';
      return;
    }
    if (!t) return;
    $('target-desc').textContent = t.desc;
    setGoal(t.x, t.y, t.name);
  };
  sel.onchange = pick;
  $('btn-science').onclick = () => {
    sel.focus();
    if (typeof sel.showPicker === 'function') sel.showPicker();
  };
  $('btn-custom').onclick = () => {
    sel.value = 'custom';
    pick();
  };
  $('dest-change').onclick = () => {
    clearRoutes();
    $('routes').innerHTML = '';
    S.goal = null; S.goalName = ''; S.selected = null; S.pickingCustom = false;
    sel.value = '';
    $('target-desc').textContent = '';
    updateSteps();
  };

  initWalker();
  $('cam-third').onclick = () => setCam('third');
  $('cam-first').onclick = () => setCam('first');
  $('cam-orbit').onclick = () => setCam('orbit');
  $('tab-bar').onclick = (e) => { if (!e.target.closest('button')) setTablet(!S.tabletUp); };
  setCam('third');
  $('plan').onclick = planRoutes;
  $('start').onclick = startEva;
  $('rockfall').onclick = rockfall;
  $('drift').onclick = drift;
  $('leak').onclick = leak;
  $('linkloss').onclick = linkLoss;
  $('deploy').onclick = deployBeacon;
  $('home').onclick = returnHome;
  $('reset').onclick = reset;
  $('autopilot-btn').onclick = () => {
    S.autopilot = !S.autopilot;
    $('autopilot-btn').classList.toggle('active', S.autopilot);
    $('autopilot-btn').innerHTML = S.autopilot ? '<span>⏸</span> Autopilot' : '<span>▶</span> Autopilot off';
    log(`Autopilot ${S.autopilot ? 'enabled' : 'disabled'}`, S.autopilot ? 'ok' : 'warn');
  };
  document.querySelectorAll('.more-tab').forEach((tab) => { tab.onclick = () => selectMoreTab(tab.dataset.tab); });
  $('more-btn').onclick = () => openMore();
  $('more-back').onclick = closeMore;
  $('more-close').onclick = closeMore;
  $('map-layers-btn').onclick = () => openMore('tab-layers');
  $('sim-open-tablet').onclick = () => setTablet(true);
  $('sim-controls-toggle').onclick = () => {
    const panel = document.querySelector('.sim-controls');
    const collapsed = panel.classList.toggle('collapsed');
    $('sim-controls-toggle').setAttribute('aria-expanded', String(!collapsed));
    $('sim-controls-toggle').querySelector('.sim-controls-chevron').textContent = collapsed ? '⌄' : '⌃';
  };
  let replayTour = false;
  $('sim-help').onclick = () => { replayTour = true; endTour(); $('intro').classList.remove('hidden'); };
  const th = S.meta.thresholds;
  // Keep source metadata intact for processing, but avoid showing institutional names in the public UI.
  $('source').innerHTML = `Terrain: HiRISE local terrain model<br>No-go thresholds: slope &gt; ${th.slope_max_deg.toFixed(0)}°, roughness &gt; ${th.rough_max_m.toFixed(2)} m.<br>`
    + `Engine: ${api.kind === 'wasm' ? 'WebAssembly in this browser' : 'local mars-server'} — no network link required.<br>`
    + (S.region ? 'Regional context: global elevation model, 463 m (Gale crater). ' : '')
    + 'Gale regional image: orbital image mosaic, 256 px/deg. '
    + 'Beacon ranges are simulated from the terrain model; science stops are auto-selected candidates.';
  $('loading').classList.add('done');
  updateSteps();
  let seen = false;
  try { seen = localStorage.getItem('mm_intro_seen') === '1'; } catch { /* storage unavailable */ }
  if ((!seen || !tourDone()) && !params.has('nointro')) $('intro').classList.remove('hidden');
  $('intro-ok').onclick = () => {
    $('intro').classList.add('hidden');
    feedback.unlockAudio();
    try { localStorage.setItem('mm_intro_seen', '1'); } catch { /* ignore */ }
    if (replayTour || !tourDone()) {
      replayTour = false;
      startTour({ tablet: () => !!S.tabletUp, goal: () => !!S.goal, planned: () => Object.keys(S.routes).length > 0 && !S.eva });
    }
  };
  log(`Loaded ${S.meta.name} (${S.meta.width}×${S.meta.height} @ ${S.meta.cell_m} m); engine ready in ${(build_ms || performance.now() - t0).toFixed(0)} ms`, 'ok');
}

const clock = new THREE.Clock();
renderer.setAnimationLoop(() => {
  const dt = Math.min(clock.getDelta(), 0.1);
  if (S.eva && !S.eva.done) { evaTick(dt); if (S.walk) S.walk.heading = S.eva.heading; } else walkTick(dt); // 抵達後恢復自由行走
  wrapGlobalMap();
  if (S.view === '3d' && !S.inGlobe && S.cam !== 'orbit') followCamera(dt);
  else controls.update();
  // 拉遠時隱藏 3D 標籤，避免全部擠在一起
  labels.domElement.style.display = S.inGlobe || (S.view === '3d' && S.cam === 'orbit' && camera.position.distanceTo(controls.target) > 9000) ? 'none' : '';
  renderer.render(scene, camera);
  updateSiteLabels();
  labels.render(scene, camera);
  renderMini();
  updateTabBar(dt);
  if (S.eva) refreshPnrBoundary();
});
initI18n();
boot().catch((e) => { $('loading-text').textContent = `Failed to load: ${e.message}`; console.error(e); });

// e2e 測試用
window.__mm = {
  S, api,
  zoomOut: () => { camera.position.set(controls.target.x - 30000, 45000, controls.target.z + 60000); },
};
